/// <summary>
///    Indicates whether the specified record in the <c>AVAPriceSurchargeTranslation</c> table exists.
/// </summary>
/// <param name="_recId">
///    The record ID of the record to check for existence.
/// </param>
/// <returns>
///    true if the specified record exists; otherwise, false.
/// </returns>
public static boolean exist(RefRecId _recId)
{
    return (AVAPriceSurchargeTranslation::find(_recId).RecId != 0);
}

/// <summary>
///     Find the specified record in the <c>AVAPriceSurchargeTranslation</c> table.
/// </summary>
/// <param name="_recId">
///     The record ID of the record to find.
/// </param>
/// <param name="_forupdate">
///     A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///     A record in the <c>AVADirNameAffixTranslation</c> table; otherwise, an empty buffer.
/// </returns>
public static AVAPriceSurchargeTranslation find(RefRecId    _recId,
                                                boolean     _forupdate = false)
{
    AVAPriceSurchargeTranslation record;

    if (!_recId)
    {
        return record;
    }
    record.selectForUpdate(_forupdate);
    select firstonly record 
    where record.RecId == _recId;

    return record;
}

/// <summary>
///     Finds all of the translated languages for a specified attribute.
/// </summary>
/// <param name="_refRecId">
///     The record ID of the related <c>AVAPriceSurcharge</c> record.
/// </param>
/// <returns>
///     A container of the translated languages.
/// </returns>
public static container findAllTranslatedLanguages(RefRecId _refRecId)
{
    AVAPriceSurchargeTranslation    locbuffer;
    List                            list;

    list = new List(Types::String);

    while select Language
    from    locbuffer
    where   locbuffer.AVAPriceSurchargeRefRecId == _refRecId
    {
        list.addEnd(locbuffer.Language);
    }

    return list.pack();
}

/// <summary>
///     Finds the specified record in the <c>AVAPriceSurchargeTranslation</c> table by using the related
///     attribute and language ID.
/// </summary>
/// <param name="_refRecId">
///     The record ID of the related <c>RefRecId</c> record.
/// </param>
/// <param name="_languageId">
///     The language ID of the record to find.
/// </param>
/// <param name="_forupdate">
///     A Boolean value that indicates whether the record is selected for update; optional.
/// </param>
/// <returns>
///     A record in the <c>AVAPriceSurchargeTranslation</c> table; otherwise, an empty record buffer.
/// </returns>
public static AVAPriceSurchargeTranslation findByAVAPriceSurchargeAndLanguage(  RefRecId    _refRecId,
                                                                                LanguageId  _languageId,
                                                                                boolean     _forupdate = false)
{
    AVAPriceSurchargeTranslation translation;

    translation.selectForUpdate(_forupdate);

    select firstonly translation
    where   translation.AVAPriceSurchargeRefRecId   == _refRecId
        &&  translation.Language                    == _languageId;

    return translation;
}
